import java.time.Duration;
import java.util.*;
import java.util.function.*;

import io.github.resilience4j.circuitbreaker.*;
import io.github.resilience4j.retry.*;

public class Main {
    public static void main(String[] args) {
        GudangPalsu gudang = new GudangPalsu("timeout", "timeout", "timeout", "timeout");
        CircuitBreaker cb = CircuitBreaker.of("gudang", CircuitBreakerConfig.custom()
                .slidingWindowSize(2).minimumNumberOfCalls(2).failureRateThreshold(50).build());
        Retry retry = Retry.of("gudang", RetryConfig.custom().maxAttempts(3).waitDuration(Duration.ofMillis(10)).build());
        Supplier<Integer> retryLuar = Retry.decorateSupplier(retry, CircuitBreaker.decorateSupplier(cb, () -> gudang.cekStok("kopi")));
        try {
            retryLuar.get();
        } catch (RuntimeException e) {
            System.out.println("Akhirnya: " + e.getClass().getSimpleName());
        }
        System.out.println("Panggilan ke gudang: " + gudang.panggilan);
    }
}

class GudangPalsu {
    private final Deque<String> jadwal;
    int panggilan;

    GudangPalsu(String... jadwal) {
        this.jadwal = new ArrayDeque<>(Arrays.asList(jadwal));
    }

    int cekStok(String barang) {
        panggilan++;
        String hasil = jadwal.isEmpty() ? "ok" : jadwal.poll();
        if (hasil.equals("timeout")) {
            throw new IllegalStateException("timeout ke gudang");
        }
        if (hasil.equals("400")) {
            throw new IllegalArgumentException("barang tidak dikenal: " + barang);
        }
        return 7;
    }
}

