class KlienGudang {
    private final GudangPalsu gudang;
    private final Map<String, Integer> terakhir = new HashMap<>();
    final Retry retry = Retry.of("gudang", RetryConfig.custom()
            .maxAttempts(2)
            .waitDuration(Duration.ofMillis(10))
            .build());
    final CircuitBreaker cb = CircuitBreaker.of("gudang", CircuitBreakerConfig.custom()
            .slidingWindowSize(4)
            .minimumNumberOfCalls(4)
            .failureRateThreshold(50)
            .build());

    KlienGudang(GudangPalsu gudang) {
        this.gudang = gudang;
    }

    String stok(String barang) {
        Supplier<Integer> dasar = () -> gudang.cekStok(barang);
        Supplier<Integer> tangguh = Retry.decorateSupplier(retry, CircuitBreaker.decorateSupplier(cb, dasar));
        try {
            int n = tangguh.get();
            terakhir.put(barang, n);
            return barang + ": " + n;
        } catch (CallNotPermittedException e) {
            return cadangan(barang, "gudang sedang tidak tersedia");
        } catch (RuntimeException e) {
            return cadangan(barang, e.getMessage());
        }
    }

    private String cadangan(String barang, String alasan) {
        Integer n = terakhir.get(barang);
        return n == null ? barang + ": tidak diketahui (" + alasan + ")" : barang + ": " + n + " (data terakhir)";
    }
}

