import java.time.Duration;
import java.util.*;
import java.util.function.*;

import io.github.resilience4j.retry.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        LayananOngkir layanan = new LayananOngkir(in.nextLine().split(","));
        Retry retry = Retry.of("ongkir", RetryConfig.custom().maxAttempts(2).waitDuration(Duration.ofMillis(10)).build());
        while (in.hasNextLine()) {
            String kota = in.nextLine();
            int ongkir = Retry.decorateSupplier(retry, () -> layanan.hitung(kota)).get();
            System.out.println(kota + ": Rp" + ongkir);
        }
    }
}

class LayananOngkir {
    private final Deque<String> jadwal;

    LayananOngkir(String... jadwal) {
        this.jadwal = new ArrayDeque<>(Arrays.asList(jadwal));
    }

    int hitung(String kota) {
        if (!jadwal.isEmpty() && jadwal.poll().equals("gagal")) {
            throw new IllegalStateException("layanan ongkir timeout");
        }
        return kota.length() * 1000;
    }
}

